mapper.select:

SELECT
    p.*,
    u.nickname AS seller_nickname,
    u.username AS seller_username,
    u.avatar AS seller_avatar,
    c.name AS category_name
FROM product p
LEFT JOIN user u ON p.seller_id = u.id
LEFT JOIN category c ON p.category_id = c.id

    AND p.status != 4

        AND p.status = #{status}


        AND p.seller_id = #{sellerId}


        AND (
            p.category_id = #{categoryId}
            OR p.category_id IN (
                SELECT id FROM category WHERE parent_id = #{categoryId}
            )
        )



            AND

                 LIKE CONCAT('%', #{term}, '%')



            AND  NOT LIKE CONCAT('%', #{excludedTerm}, '%')



        AND p.price >= #{minPrice}


        AND p.price <= #{maxPrice}


        AND p.condition_level = #{conditionLevel}




        ORDER BY p.price ASC, p.id DESC


        ORDER BY p.price DESC, p.id DESC


        ORDER BY p.view_count DESC, p.create_time DESC, p.id DESC


        ORDER BY p.create_time DESC, p.id DESC
